import { Swiper, SwiperSlide } from "swiper/react";
import { Autoplay, Pagination, Navigation, EffectCreative } from "swiper/modules";
import "swiper/css";
import "swiper/css/pagination";
import "swiper/css/navigation";
import "swiper/css/effect-creative";

// Example images (replace with your actual image imports or URLs)
const sliderData = [
  { img: "/images/slide1.jpg", text: "Live Streaming Fun" },
  { img: "/images/slide2.jpg", text: "Connect with Friends" },
  { img: "/images/slide3.jpg", text: "Earn While You Stream" },
  { img: "/images/slide4.jpg", text: "Join Interactive Games" },
  { img: "/images/slide5.jpg", text: "Be Part of the Community" },
  { img: "/images/slide6.jpg", text: "Win Exciting Rewards" },
  { img: "/images/slide7.jpg", text: "Stream Anytime, Anywhere" },
  { img: "/images/slide8.jpg", text: "Discover New Talents" },
  { img: "/images/slide9.jpg", text: "Host Live Shows" },
  { img: "/images/slide10.jpg", text: "Share Your Moments" },
];

export default function Front() {
  return (
    <section className="z-10">
      <Swiper
        modules={[Autoplay, Pagination, Navigation, EffectCreative]}
        autoplay={{ delay: 3000, disableOnInteraction: false }}
        pagination={{ clickable: true }}
        navigation={true}
        loop={true}
        grabCursor={true}
        effect="creative"
        creativeEffect={{
          prev: {
            shadow: true,
            translate: ["-20%", 0, -1],
            rotate: [0, 100, 0],
          },
          next: {
            shadow: true,
            translate: ["100%", 0, 0],
            rotate: [0, -100, 0],
          },
        }}
        className="h-[620px] sm:rounded-3xl overflow-hidden"
      >
        {sliderData.map((slide, index) => (
          <SwiperSlide key={index}>
            <div
              className="relative w-full h-full bg-cover bg-center"
              style={{ backgroundImage: `url(${slide.img})` }}
            >
              {/* Overlay */}
              <div className="absolute inset-0 bg-black/40"></div>

              {/* Text on Image */}
              <div className="absolute inset-0 flex flex-col justify-center items-center text-center text-white px-6">
                <h2 className="text-3xl sm:text-5xl font-bold mb-4 drop-shadow-lg animate-fadeIn">
                  {slide.text}
                </h2>
              </div>
            </div>
          </SwiperSlide>
        ))}
      </Swiper>
    </section>
  );
}
